const { LRUCache } = require('./src/lru');
const assert = require('node:assert/strict');
// capacity validation
for (const bad of [0, -1, 1.5, Infinity, NaN, '2', undefined]) {
  assert.throws(() => new LRUCache(bad), RangeError, String(bad));
}
// get refreshes entry with undefined value
const c = new LRUCache(2);
c.set('a', undefined).set('b', 2);
assert.equal(c.get('a'), undefined);
c.set('c', 3);
assert.equal(c.has('a'), true);
assert.equal(c.has('b'), false);
// update does not evict unrelated or grow
const d = new LRUCache(2);
d.set('a', 1).set('b', 2);
d.set('a', 10);
assert.equal(d.size, 2);
assert.equal(d.get('a'), 10);
assert.equal(d.get('b'), 2);
// arbitrary keys
const e = new LRUCache(3);
const k = {};
e.set(k, 'obj').set(0, 'zero').set(null, 'null');
assert.equal(e.get(k), 'obj');
assert.equal(e.get(0), 'zero');
assert.equal(e.get(null), 'null');
// delete preserves recency of survivors
const f = new LRUCache(2);
f.set('a', 1).set('b', 2);
f.delete('a');
f.set('c', 3);
assert.equal(f.has('b'), true);
assert.equal(f.has('c'), true);
// independence
const g = new LRUCache(1), h = new LRUCache(1);
g.set('x', 1);
assert.equal(h.size, 0);
console.log('extra checks passed');
"

